	// dropped before they are sent over the wire
	seenActorID := make(map[uuid.UUID]struct{}, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}
		if _, ok := seenActorID[o.ActorID]; ok {
			continue
		}
		seenActorID[o.ActorID] = struct{}{}
		pkActorID = append(pkActorID, o.ActorID)
	}
	PKArgExpr := psql.Any(psql.Cast(psql.Arg(pkActorID), "uuid[]"))

	return Members.Query(append(mods,
		sm.Where(Members.Columns.ID.EQ(PKArgExpr)),
	)...)
