func (o *ProductCorrection) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "ActorMember":
		rel, ok := retrieved.(*Member)
		if !ok {
			return fmt.Errorf("productCorrection cannot load %T as %q", retrieved, name)
		}

		o.R.ActorMember = rel
		o.R.Loaded.ActorMember = true

		if rel != nil {
			rel.R.ActorProductCorrections = ProductCorrectionSlice{o}
		}
		return nil
	case "ProductVariant":
		rel, ok := retrieved.(*ProductVariant)
		if !ok {
			return fmt.Errorf("productCorrection cannot load %T as %q", retrieved, name)
		}

		o.R.ProductVariant = rel
		o.R.Loaded.ProductVariant = true

		if rel != nil {
			rel.R.ProductCorrections = ProductCorrectionSlice{o}
		}
		return nil
	case "PurchaseItem":
		rel, ok := retrieved.(*PurchaseItem)
		if !ok {
			return fmt.Errorf("productCorrection cannot load %T as %q", retrieved, name)
		}

		o.R.PurchaseItem = rel
		o.R.Loaded.PurchaseItem = true

		if rel != nil {
			rel.R.ProductCorrections = ProductCorrectionSlice{o}
		}
		return nil
	default:
		return fmt.Errorf("productCorrection has no relationship %q", name)
	}
}

