// LoadProductVariant loads the productCorrection's ProductVariant into the .R struct
func (os ProductCorrectionSlice) LoadProductVariant(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	productVariants, err := os.ProductVariant(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.ProductVariant = nil
		o.R.Loaded.ProductVariant = true
	}
	for _, o := range os {
		if o == nil {
			continue
		}

		for _, rel := range productVariants {

			if !(o.HouseholdID == rel.HouseholdID) {
				continue
			}

			if !(o.ProductVariantID == rel.ID) {
				continue
			}

			rel.R.ProductCorrections = append(rel.R.ProductCorrections, o)

			o.R.ProductVariant = rel
			break
		}
	}

	return nil
}

