type productCorrectionJoins[Q dialect.Joinable] struct {
	typ            string
	ActorMember    modAs[Q, memberColumns]
	ProductVariant modAs[Q, productVariantColumns]
	PurchaseItem   modAs[Q, purchaseItemColumns]
}

func (j productCorrectionJoins[Q]) aliasedAs(alias string) productCorrectionJoins[Q] {
	return buildProductCorrectionJoins[Q](buildProductCorrectionColumns(alias), j.typ)
}

func buildProductCorrectionJoins[Q dialect.Joinable](cols productCorrectionColumns, typ string) productCorrectionJoins[Q] {
	return productCorrectionJoins[Q]{
		typ: typ,
		ActorMember: modAs[Q, memberColumns]{
			c: Members.Columns,
			f: func(to memberColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Members.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.ActorID),
					))
				}

				return mods
			},
		},
		ProductVariant: modAs[Q, productVariantColumns]{
			c: ProductVariants.Columns,
			f: func(to productVariantColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, ProductVariants.NameExpr().As(to.Alias())).On(
						to.HouseholdID.EQ(cols.HouseholdID), to.ID.EQ(cols.ProductVariantID),
					))
				}

				return mods
			},
		},
		PurchaseItem: modAs[Q, purchaseItemColumns]{
			c: PurchaseItems.Columns,
			f: func(to purchaseItemColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, PurchaseItems.NameExpr().As(to.Alias())).On(
						to.HouseholdID.EQ(cols.HouseholdID), to.PurchaseID.EQ(cols.PurchaseID), to.ID.EQ(cols.ItemID),
					))
				}

				return mods
			},
		},
	}
}
